struct RingBuffer {
    static constexpr int MAX_CAP = 1024;

    RingBuffer(int capacity) : cap_(capacity), head_(0), tail_(0), count_(0) {}

    bool push(int value) {
        if (full()) return false;
        buf_[tail_] = value;
        tail_ = (tail_ + 1) % cap_;
        ++count_;
        return true;
    }

    bool pop(int& out) {
        if (empty()) return false;
        out = buf_[head_];
        head_ = (head_ + 1) % cap_;
        --count_;
        return true;
    }

    int  size() const { return count_; }
    bool empty() const { return count_ == 0; }
    bool full() const { return count_ == cap_; }

private:
    int buf_[MAX_CAP];
    int cap_;
    int head_;
    int tail_;
    int count_;
};
