struct Tape {
    std::vector<double> vals;
    std::vector<double> grads;
    std::vector<int> parent1;
    std::vector<int> parent2;
    std::vector<int> op; // 0: constant, 1: input, 2: add, 3: mul, 4: sin, 5: exp

    int constant(double v) {
        int id = vals.size();
        vals.push_back(v);
        grads.push_back(0.0);
        parent1.push_back(-1);
        parent2.push_back(-1);
        op.push_back(0);
        return id;
    }

    int input(double v) {
        int id = vals.size();
        vals.push_back(v);
        grads.push_back(0.0);
        parent1.push_back(-1);
        parent2.push_back(-1);
        op.push_back(1);
        return id;
    }

    int add(int a, int b) {
        int id = vals.size();
        vals.push_back(vals[a] + vals[b]);
        grads.push_back(0.0);
        parent1.push_back(a);
        parent2.push_back(b);
        op.push_back(2);
        return id;
    }

    int mul(int a, int b) {
        int id = vals.size();
        vals.push_back(vals[a] * vals[b]);
        grads.push_back(0.0);
        parent1.push_back(a);
        parent2.push_back(b);
        op.push_back(3);
        return id;
    }

    int sin_(int a) {
        int id = vals.size();
        vals.push_back(std::sin(vals[a]));
        grads.push_back(0.0);
        parent1.push_back(a);
        parent2.push_back(-1);
        op.push_back(4);
        return id;
    }

    int exp_(int a) {
        int id = vals.size();
        vals.push_back(std::exp(vals[a]));
        grads.push_back(0.0);
        parent1.push_back(a);
        parent2.push_back(-1);
        op.push_back(5);
        return id;
    }

    double value(int node) const {
        return vals[node];
    }

    void backward(int root) {
        // Reset all gradients
        for (auto& g : grads) g = 0.0;
        grads[root] = 1.0;

        // Process nodes in reverse order of creation
        for (int i = (int)vals.size() - 1; i >= 0; --i) {
            if (grads[i] == 0.0) continue;

            int p1 = parent1[i];
            int p2 = parent2[i];

            switch (op[i]) {
                case 2: // add
                    if (p1 >= 0) grads[p1] += grads[i];
                    if (p2 >= 0) grads[p2] += grads[i];
                    break;
                case 3: // mul
                    if (p1 >= 0) grads[p1] += grads[i] * vals[p2];
                    if (p2 >= 0) grads[p2] += grads[i] * vals[p1];
                    break;
                case 4: // sin
                    if (p1 >= 0) grads[p1] += grads[i] * std::cos(vals[p1]);
                    break;
                case 5: // exp
                    if (p1 >= 0) grads[p1] += grads[i] * vals[i];
                    break;
                default:
                    break;
            }
        }
    }

    double grad(int node) const {
        return grads[node];
    }
};
