module async_fifo #(parameter WIDTH = 8, parameter DEPTH = 8)
  (input wclk, input wrst_n, input winc, input [WIDTH-1:0] wdata, output wfull,
   input rclk, input rrst_n, input rinc, output [WIDTH-1:0] rdata, output rempty);

  localparam PTR_W = $clog2(DEPTH);
  localparam MEM_W = PTR_W + 1;

  // Memory
  reg [WIDTH-1:0] mem [0:DEPTH-1];

  // Write domain
  reg [MEM_W-1:0] wptr_bin;
  reg [PTR_W-1:0] wptr_gray;
  reg [PTR_W-1:0] rptr_gray_sync1, rptr_gray_sync2;
  reg [MEM_W-1:0] rptr_bin_sync;

  // Read domain
  reg [MEM_W-1:0] rptr_bin;
  reg [PTR_W-1:0] rptr_gray;
  reg [PTR_W-1:0] wptr_gray_sync1, wptr_gray_sync2;
  reg [MEM_W-1:0] wptr_bin_sync;

  // Full/Empty flags
  wire wfull;
  wire rempty;

  // Binary to Gray conversion
  function [PTR_W-1:0] bin2gray;
    input [MEM_W-1:0] bin;
    begin
      bin2gray = (bin[PTR_W-1:0] ^ (bin[PTR_W-1:0] >> 1));
    end
  endfunction

  // Gray to Binary conversion
  function [MEM_W-1:0] gray2bin;
    input [PTR_W-1:0] gray;
    reg [MEM_W-1:0] bin;
    integer i;
    begin
      bin[MEM_W-1:0] = 0;
      bin[PTR_W-1:0] = gray[PTR_W-1:0];
      for (i = PTR_W-2; i >= 0; i = i - 1)
        bin[i] = bin[i+1] ^ gray[i];
      gray2bin = bin;
    end
  endfunction

  // Write domain logic
  always @(posedge wclk or negedge wrst_n) begin
    if (!wrst_n) begin
      wptr_bin <= {MEM_W{1'b0}};
      wptr_gray <= {PTR_W{1'b0}};
    end else if (winc && !wfull) begin
      wptr_bin <= wptr_bin + 1'b1;
      wptr_gray <= bin2gray(wptr_bin + 1'b1);
    end
  end

  // Synchronize read pointer gray into write domain
  always @(posedge wclk or negedge wrst_n) begin
    if (!wrst_n) begin
      rptr_gray_sync1 <= {PTR_W{1'b0}};
      rptr_gray_sync2 <= {PTR_W{1'b0}};
    end else begin
      rptr_gray_sync1 <= rptr_gray;
      rptr_gray_sync2 <= rptr_gray_sync1;
    end
  end

  // Convert synchronized gray to binary in write domain
  always @(*) begin
    rptr_bin_sync = gray2bin(rptr_gray_sync2);
  end

  // Full condition: write pointer has lapped read pointer
  // wptr_bin == rptr_bin_sync + DEPTH
  // In gray terms, this is when the MSB of wptr_gray differs from rptr_gray_sync2
  // and the lower bits are equal
  assign wfull = (wptr_gray == {~rptr_gray_sync2[PTR_W-1], rptr_gray_sync2[PTR_W-2:0]});

  // Read domain logic
  always @(posedge rclk or negedge rrst_n) begin
    if (!rrst_n) begin
      rptr_bin <= {MEM_W{1'b0}};
      rptr_gray <= {PTR_W{1'b0}};
    end else if (rinc && !rempty) begin
      rptr_bin <= rptr_bin + 1'b1;
      rptr_gray <= bin2gray(rptr_bin + 1'b1);
    end
  end

  // Synchronize write pointer gray into read domain
  always @(posedge rclk or negedge rrst_n) begin
    if (!rrst_n) begin
      wptr_gray_sync1 <= {PTR_W{1'b0}};
      wptr_gray_sync2 <= {PTR_W{1'b0}};
    end else begin
      wptr_gray_sync1 <= wptr_gray;
      wptr_gray_sync2 <= wptr_gray_sync1;
    end
  end

  // Convert synchronized gray to binary in read domain
  always @(*) begin
    wptr_bin_sync = gray2bin(wptr_gray_sync2);
  end

  // Empty condition: read pointer equals write pointer
  assign rempty = (rptr_gray == wptr_gray_sync2);

  // Memory write
  always @(posedge wclk) begin
    if (winc && !wfull)
      mem[wptr_bin[PTR_W-1:0]] <= wdata;
  end

  // Memory read
  assign rdata = mem[rptr_bin[PTR_W-1:0]];

endmodule
