__global__ void matmul(const float* A, const float* B, float* C,
                       int M, int N, int K) {
    __shared__ float As[16][16];
    __shared__ float Bs[16][16];

    const int row = blockIdx.y * 16 + threadIdx.y;
    const int col = blockIdx.x * 16 + threadIdx.x;

    float sum = 0.0f;

    for (int k = 0; k < K; k += 16) {
        // Load tile of A: As[threadIdx.y][threadIdx.x] = A[row][k + threadIdx.x]
        int a_col = k + threadIdx.x;
        if (row < M && a_col < K)
            As[threadIdx.y][threadIdx.x] = A[row * K + a_col];
        else
            As[threadIdx.y][threadIdx.x] = 0.0f;

        // Load tile of B: Bs[threadIdx.y][threadIdx.x] = B[k + threadIdx.y][col]
        int b_row = k + threadIdx.y;
        if (b_row < K && col < N)
            Bs[threadIdx.y][threadIdx.x] = B[b_row * N + col];
        else
            Bs[threadIdx.y][threadIdx.x] = 0.0f;

        __syncthreads();

        // Compute partial dot product for this tile
        #pragma unroll
        for (int t = 0; t < 16; t++) {
            sum += As[threadIdx.y][t] * Bs[t][threadIdx.x];
        }

        __syncthreads();
    }

    if (row < M && col < N) {
        C[row * N + col] = sum;
    }
}
